window.initMapScript=()=>{let t=[];t=window.gutentorGoogleMaps,t&&t.forEach(t=>{const e=new google.maps.Map(document.getElementById(t.container),{center:{lat:Number(t.attributes.latitude),lng:Number(t.attributes.longitude)},gestureHandling:"cooperative",zoom:t.attributes.zoom,mapTypeId:t.attributes.type,draggable:t.attributes.draggable,mapTypeControl:t.attributes.mapTypeControl,zoomControl:t.attributes.zoomControl,fullscreenControl:t.attributes.fullscreenControl,streetViewControl:t.attributes.streetViewControl});if(!t.attributes.id&&t.attributes.location){const o={query:t.attributes.location,fields:["name","geometry"]};new google.maps.places.PlacesService(e).findPlaceFromQuery(o,(t,o)=>{o===google.maps.places.PlacesServiceStatus.OK&&0<t.length&&e.setCenter(t[0].geometry.location)})}t.attributes.markers&&0<t.attributes.markers.length&&t.attributes.markers.forEach(t=>{let o;o=t.hasOwnProperty("e4Lat")?new google.maps.LatLng(t.e4Lat,t.e4Lon):new google.maps.LatLng(t.latitude,t.longitude);const n=new google.maps.Marker({position:o,map:e,title:t.title});(t.title||t.description)&&(window.infoWindow||(window.infoWindow=new google.maps.InfoWindow),n.addListener("click",()=>{window.infoWindow&&(window.infoWindow.setContent(function(t){return`<div class="gutentor-map-overview"><h6 class="gutentor-map-overview-title">${t.title}</h6><div class="gutentor-map-overview-content">${t.description?`<p>${t.description}</p>`:""}</div></div>`}(t)),window.infoWindow.open(e,n))}))})})};